export function createRound(e){return{phase:"ready",elapsed:0,settled:0,seconds:e.seconds}}export function resetRound(e){return e.phase="ready",e.elapsed=0,e.settled=0,e}export function freePlay(e){return e.phase="free",e.elapsed=0,e.settled=0,e}export function canBlow(e){return e.phase==="ready"||e.phase==="playing"||e.phase==="free"}export function timeLeft(e){return Math.max(0,e.seconds-e.elapsed)}export function stepRound(e,t,s,l){const a=t>0?t:0;return e.phase==="ready"?s.blowing?(e.phase="playing","start"):null:e.phase==="playing"?(e.elapsed+=a,e.elapsed>=e.seconds?(e.elapsed=e.seconds,e.phase="settling",e.settled=0,"time-up"):null):e.phase==="settling"&&(e.settled+=a,s.moving===0&&e.settled>=l.settleMin||e.settled>=l.settleMax)?(e.phase="done","done"):null}
